class Counter:
    def __init__(self, words):
        self.freq = {}
        for w in words:
            self.freq[w] = self.freq.get(w, 0) + 1

class TopWord(Counter):
    def __init__(self, words, min_len):
        self.min_len = min_len

    def top(self):
        best, best_n = None, 0
        for w, n in self.freq.items():
            if len(w) >= self.min_len and n > best_n:
                best, best_n = w, n
        return best

print(TopWord(["aa", "b", "aa"], 2).top())

