def safe_min(iterable, key=None, default=None):
    it = iter(iterable)
    try:
        best = next(it)
    except StopIteration:
        if default is None:
            raise ValueError("empty")
        return default
    k = key or (lambda v: v)
    best_k = k(best)
    for x in it:
        kx = k(x)
        if kx < best_k:
            best, best_k = x, kx
    return best

import csv, math
G = 9.8
legs = {}
with open("d1.csv") as f:
    for row in csv.DictReader(f):
        legs[row["NAME"]] = float(row["LEG_LENGTH"])
out = []
with open("d2.csv") as f:
    for row in csv.DictReader(f):
        if row["STANCE"] == "bipedal" and row["NAME"] in legs:
            leg = legs[row["NAME"]]
            speed = (float(row["STRIDE_LENGTH"]) / leg - 1) * math.sqrt(leg * G)
            out.append((row["NAME"], speed))
sorted(out, key=lambda t: t[1], reverse=True)
for name, _ in out:
    print(name)
